<script setup lang="ts">import { computed } from 'vue';import { useCalendarStore } from '../../stores/calendar.store';const c=useCalendarStore();const days=computed(()=>{const d=c.cursor,y=d.getFullYear(),m=d.getMonth(),first=(new Date(y,m,1).getDay()+6)%7,count=new Date(y,m+1,0).getDate(),out:Array<{key:string,date?:Date}> =[];for(let i=0;i<first;i++)out.push({key:`p${i}`});for(let i=1;i<=count;i++)out.push({key:`d${i}`,date:new Date(y,m,i)});return out});function eventsFor(d?:Date){if(!d)return[];return c.sortedEvents.filter(e=>{const x=new Date(e.start);return x.getFullYear()===d.getFullYear()&&x.getMonth()===d.getMonth()&&x.getDate()===d.getDate()}).slice(0,3)}</script><template><div class="month"><div v-for="w in ['Lun','Mar','Mer','Gio','Ven','Sab','Dom']" :key="w" class="weekday">{{w}}</div><div v-for="d in days" :key="d.key" class="day" :class="{blank:!d.date,today:d.date?.toDateString()===new Date().toDateString()}"><b v-if="d.date">{{d.date.getDate()}}</b><div v-if="d.date" class="markers"><span v-for="e in eventsFor(d.date)" :key="e.id" :title="e.title">{{e.title}}</span></div></div></div></template><style scoped>.month{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:1px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.08);border-radius:18px;overflow:hidden}.weekday{padding:.7rem;text-align:center;font-size:var(--font-xs);text-transform:uppercase;letter-spacing:.1em;color:var(--text-muted);background:#151e19}.day{min-height:112px;background:#121a16;padding:.55rem;overflow:hidden}.day b{display:grid;place-items:center;width:28px;height:28px;font-size:.78rem}.day.today b{border-radius:50%;background:var(--accent);color:#142019}.markers{display:grid;gap:.25rem;margin-top:.4rem}.markers span{font-size:.72rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding:.25rem .35rem;border-radius:7px;background:rgba(158,205,182,.13)}@media(max-width:600px){.weekday{padding:.45rem .1rem;font-size:.62rem}.day{min-height:54px;padding:.28rem}.day b{width:23px;height:23px;font-size:.7rem}.markers span{font-size:0;width:5px;height:5px;border-radius:50%;padding:0;background:var(--accent);display:inline-block}.markers{display:flex;gap:3px;margin:.25rem 0 0 .25rem}}</style>
